// Where each drawn map icon sits on the map canvas: [left, top, width, height] in map units.
// Change a box here only if a new drawing needs a different frame; the icon files themselves live in artwork/map/.
export type Box = [left: number, top: number, width: number, height: number]

// The canvas is 7400 x 2900 units (about 11.7 x 4.6 miles) and runs from x = -3400 to x = 4000 and
// y = -1000 to y = 1900, so Guildford is at the left and Dorking at the right. The route sits in the
// middle; the page lets you drag the map around within it and zoom out (never in past the starting view).
// Phones start on the 600 x 900 slice around the route, wider screens on the middle 1800 x 900.
export const MAP_X = -3400
export const MAP_Y = -1000
export const MAP_W = 7400
export const MAP_H = 2900

export const landmarks = {
  church: [177.3, 125.2, 94.4, 105.8],
  bus: [295.1, 466.6, 95.0, 77.4],
  venue: [305.3, 622.8, 133.9, 80.2],
} satisfies Record<string, Box>

// The red bus route is a full-canvas drawing (artwork/map/route.svg) that lines up with the base map.
export const route: Box = [MAP_X, MAP_Y, MAP_W, MAP_H]

